# If the text has whitespace but no words, what should wrap do?
# Let's check with a manual implementation that preserves spacing

def wrap_fixed(text, width):
    # Handle text with only whitespace
    if not text.strip():
        return [text] if text else []

    lines = []
    cur = ""
    for w in text.split():
        extra = len(w) + (1 if cur else 0)
        if len(cur) + extra > width:
            lines.append(cur)
            cur = w
        else:
            cur = f"{cur} {w}" if cur else w
    if cur:
        lines.append(cur)
    return lines

